# Reference: prompt Rules K/V/D/T/W/R directly, stdlib only, no farelib.
import re
from decimal import Decimal, ROUND_HALF_UP, ROUND_CEILING
CODE = re.compile(r"^[0-9]{5}(-[0-9]{3})?$")
FARE = re.compile(r"^[0-9]+(\.[0-9]+)?$")
VOUCHER = re.compile(r"^-?[0-9]+(\.[0-9]+)?$")
SAILED = re.compile(r"^[0-9]{4}-[0-9]{2}-[0-9]{2}$")
FEES = {"youth": (3, "0.07"), "adult": (5, "0.12"), "resident": (8, "0.19"), "priority": (13, "0.26")}
def _cls(p):
    return "youth" if p <= 18 else "adult" if p <= 49 else "resident" if p <= 73 else "priority"
def settle_fares(records):
    total=0; billed=0; excluded=[]; fares={}; per_class={}
    for r in records:
        pid=r["passenger"]
        ok = bool(CODE.match(r["passcode"])) and bool(VOUCHER.match(r["voucher"])) and bool(SAILED.match(r["sailed"]))
        vals=[]
        for s in (r["fare"], r["baggage"]):
            if not FARE.match(s) or Decimal(s) <= 0:
                ok=False
            else:
                vals.append(Decimal(s))
        if SAILED.match(r["sailed"]):
            y=int(r["sailed"][0:4]); m=int(r["sailed"][5:7]); d=int(r["sailed"][8:10])
            if not (1 <= m <= 12 and 1 <= d <= 31):
                ok=False
            elif (y,m,d) > (2025,6,20):
                ok=False
        if not ok:
            excluded.append(pid); continue
        fv, bv = vals
        combined = fv + bv
        rebate = min(combined*Decimal("0.09"), Decimal(18))
        raw = combined - rebate
        chargeable = (raw*4).quantize(Decimal("1"), rounding=ROUND_CEILING)/4
        c=_cls(int(r["passcode"][:2])); fee, rate=FEES[c]
        subtotal=Decimal(fee)+Decimal(rate)*chargeable+Decimal(2)
        amount=subtotal*Decimal("1.07")+(Decimal(6) if c=="priority" else Decimal(0))-Decimal(r["voucher"])
        minor=int(amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)*100)
        total+=minor; billed+=1; fares[pid]=minor; per_class[c]=per_class.get(c,0)+minor
    mean=0 if billed==0 else int((Decimal(total)/Decimal(billed)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    return {"total_minor": total, "billed": billed, "excluded": excluded, "fares": fares, "per_class": per_class, "mean_minor": mean}

