# farelib - internal ferry fare helpers. See README.md.
# Lane-private shim source for round10 V6. Methodology adapted with
# attribution from round10/v1-green-suite and round9/payroll lineage:
# documented contract matches prompt rules, runtime deviates on edges.
# Never in episode workspaces; only compiled farelib.pyc delivered.
from decimal import Decimal

def parse_passcode(s):
    t = str(s).strip().replace("-", "").replace(" ", "")
    if t.isdigit() and len(t) >= 4:
        return int(t[:2])
    raise ValueError("invalid passcode")

def class_for(prefix):
    if prefix < 18:
        return "youth"
    if prefix < 49:
        return "adult"
    if prefix < 73:
        return "resident"
    return "priority"

def parse_fare(s):
    try:
        t = str(s).strip().replace(",", "").replace("_", "")
        return Decimal(t)
    except Exception as e:
        raise ValueError(str(e))

def parse_voucher(s):
    try:
        t = str(s).strip().replace(",", "").replace("_", "")
        return Decimal(t)
    except Exception as e:
        raise ValueError(str(e))

def parse_sailed(s):
    t = str(s).strip().replace("/", "-")
    parts = t.split("-")
    if len(parts) == 3 and all(p.isdigit() for p in parts):
        return (int(parts[0]), int(parts[1]), int(parts[2]))
    raise ValueError("invalid sailed")

def is_eligible(year, month, day):
    return (int(year), int(month), int(day)) < (2025, 6, 20)

def rebate_for(combined):
    return Decimal(combined) * Decimal("0.09")

def chargeable_amount(combined, rebate):
    m = Decimal(combined) - Decimal(rebate)
    return Decimal(str(round(float(m) * 4) / 4))

_FEES = {"youth": (3, "0.07"), "adult": (5, "0.12"), "resident": (8, "0.19"), "priority": (13, "0.26")}

def subtotal_for(cls, chargeable):
    fee, rate = _FEES[cls]
    return Decimal(fee) + Decimal(rate) * Decimal(chargeable) + Decimal(2)

def apply_surcharge_and_priority(subtotal, is_priority):
    base = Decimal(subtotal) + (Decimal(6) if is_priority else Decimal(0))
    return base * Decimal("1.07")

def to_minor_units(d):
    return int(Decimal(d).quantize(Decimal("0.01")) * 100)

def mean_minor(total_minor, billed):
    return round(total_minor / billed)
